# Inject Spanish
for f_name in [
    "calculadora-de-calorias-para-perder-peso-y-ganar-musculo.html",
    "calculadora-de-calorias.html",
    "calculadora-de-tmb-y-gasto-calorico.html",
    "calcular-calorias-de-alimentos-y-macros.html"
]:
    path = os.path.join(r"d:\TOOLS WEB TOOLS\kiro calorie\public\country\spain", f_name)
    if os.path.exists(path):
        with open(path, "r", encoding="utf-8") as f:
            content = f.read()
        if "Lo que dicen nuestros usuarios" not in content:
            # Inject right before Contenido Sugerido or closing main/body
            # Finding typical section to inject before
            match = re.search(r'<section[^>]*>(?:(?!<section).)*?Contenido Sugerido', content, flags=re.IGNORECASE|re.DOTALL)
            if match:
                idx = match.start()
                content = content[:idx] + spanish_html + "\n" + content[idx:]
            else:
                content = content.replace("</body>", spanish_html + "\n</body>")
            with open(path, "w", encoding="utf-8") as f:
                f.write(content)

